function syncSliders(){ids.forEach(id=>{const d=num(id);const units={tempSP:' °C',levelSP:'%',heatLoad:' °C equiv.',tankLoad:'',restriction179:'%',restriction180:'%',speedLimit:'%',manualSpeed:'%',pumpGain:'',p01:'',p02:'',sp179Manual:' índice',sp180Manual:' índice',manualValve179:'%',manualValve180:'%'};const suffix=units[id]||'';let digits=['tempSP','levelSP','heatLoad','tankLoad','pumpGain'].includes(id)?1:0;if(id==='pumpGain')digits=2;add(id+'Val',fmt(d,digits)+suffix)});}
function step(dt){const o=options(), elapsed=s.t;
  if(oscillation){ /* Pequena oscilação didática explícita: carga variável nos dois ramais */ }
  // Mestres térmico e de inventário; ganhos, inércias e vazões são deliberadamente ilustrativos.
  const errT=s.temp-o.tempSP, errL=s.level-o.levelSP; // Saída F-3906 -> F-3907: nível alto requer maior retirada.
  if(o.ticMode==='auto')s.iT=clamp(s.iT+errT*dt,-230,230);else s.iT=clamp((o.sp179Manual-60-2.7*errT)/.22,-230,230);
   if(o.licMode==='auto')s.iL=clamp(s.iL+errL*dt,-210,210);else s.iL=clamp((o.sp180Manual-43-1.85*errL)/.15,-210,210);
  const wobble=oscillation?2.1*Math.sin(elapsed*0.45):0;
  s.sp179=o.ticMode==='manual'?o.sp179Manual:clamp(60+2.7*errT+0.22*s.iT+wobble,9,105);
  s.sp180=o.licMode==='manual'?o.sp180Manual:clamp(43+1.85*errL+0.15*s.iL-wobble,5,95);
  // FIC: servo proporcional-integral com anti-windup simplificado e inércia de válvula.
  const measured179=s.q179true+(o.sensorFault==='bias179'?12:extraBias);
  const e179=s.sp179-measured179,e180=s.sp180-s.q180true;
  if(o.fic179Mode==='auto') s.i179=clamp(s.i179+e179*dt,-140,140);else s.i179=clamp((o.manualValve179-70-(s.sp179-60)*1.12-e179*.9)/.26,-140,140);
   if(o.fic180Mode==='auto') s.i180=clamp(s.i180+e180*dt,-140,140);else s.i180=clamp((o.manualValve180-60-(s.sp180-43)*1.35-e180*1.1)/.28,-140,140);
  const v179ref=o.fic179Mode==='manual'?o.manualValve179:clamp(70+(s.sp179-60)*1.12+e179*0.9+s.i179*.26,0,100);
  const v180ref=o.fic180Mode==='manual'?o.manualValve180:clamp(60+(s.sp180-43)*1.35+e180*1.10+s.i180*.28,0,100);
  s.mv179+= (v179ref-s.mv179)*(1-Math.exp(-dt/1.3));s.mv180+=(v180ref-s.mv180)*(1-Math.exp(-dt/1.3));
   if(o.valveFault!=='179')s.v179+=(s.mv179-s.v179)*(1-Math.exp(-dt/2.5));
   if(o.valveFault!=='180')s.v180+=(s.mv180-s.v180)*(1-Math.exp(-dt/2.5));
  // Parte reproduzida exatamente da lógica mostrada no desenho. RV/RV1 assumidos como MV dos FICs para simulação.
  s.x=s.mv179-o.p01;s.y=s.mv180-o.p02;s.cpv=Math.max(s.x,s.y);s.winner=s.x>=s.y?179:180;
  // Mapeamento CPV -> rotação NÃO confirmado: somente opção educativa selecionável.
  const target=o.pumpMode==='manual'?Math.min(o.manualSpeed,o.speedLimit):o.pumpMode==='hold'?s.speed:clamp(80+o.pumpGain*s.cpv,55,o.speedLimit);
  s.speed+= (target-s.speed)*(1-Math.exp(-dt/10));s.speed=clamp(s.speed,45,110);
  const pumpFactor=Math.pow(Math.max(.1,s.speed)/80,1.60);
  const flow179=s.v179*(60/70)*pumpFactor*(1-o.restriction179/100*.92);
  const flow180=s.v180*(43/60)*pumpFactor*(1-o.restriction180/100*.92);
  s.q179true+=(flow179-s.q179true)*(1-Math.exp(-dt/2.2));s.q180true+=(flow180-s.q180true)*(1-Math.exp(-dt/2.2));
  s.q179=s.q179true+(o.sensorFault==='bias179'?12:extraBias);s.q180=s.q180true;
  const thermalEq=115+o.heatLoad-.38*(s.q179true-60);
  s.temp+=(thermalEq-s.temp)*(1-Math.exp(-dt/30));
  s.level=clamp(s.level+(.039*(43-s.q180true+o.tankLoad))*dt,0,100); // FCV-180 = saída: mais FT-180 diminui inventário F-3906.
  s.tempErr=s.temp-o.tempSP;s.levelErr=s.level-o.levelSP;
  s.t+=dt;
  evaluateChallenge(dt);detectEvents(o);
  sampleCounter+=dt;if(sampleCounter>=.85){sampleCounter=0;hist.push({t:s.t,temp:s.temp,tempSP:o.tempSP,level:s.level,levelSP:o.levelSP,q179:s.q179,q180:s.q180,sp179:s.sp179,sp180:s.sp180,speed:s.speed,cpv:s.cpv,x:s.x,y:s.y,mv179:s.mv179,mv180:s.mv180,v179:s.v179,v180:s.v180});if(hist.length>180)hist.shift();}
}
function pulse(which){if(which==='temp'){s.temp=clamp(s.temp+6,65,165);toast('Pulso de +6 °C aplicado à temperatura virtual. Observe a cascata TIC → FIC.');}else{s.level=clamp(s.level-10,0,100);toast('Queda instantânea de 10 pontos percentuais no nível virtual.');}logEvent(which==='temp'?'Pulso +6 °C no TT-249 virtual.':'Pulso −10 p.p. no LT-163 virtual.','disturbance');updateRender();}
